function getValue(address asset, address baseToken, uint256 amount) public view returns (uint256) {
    if (asset == baseToken) {
        return amount;
    }

    (address primarySource, bool isPrimaryInverse) = getSourceOfAsset(asset, baseToken);
    if (primarySource == address(0)) {
        revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(asset, baseToken, primarySource);
    }
    address decimalsSource = isPrimaryInverse ? baseToken : asset;
    decimalsSource = decimalsSource == ETH || decimalsSource == USD ? primarySource : decimalsSource;
    return getValueFromChainlinkFeed(
        AggregatorV3Interface(primarySource), amount, getTokenDecimals(decimalsSource), isPrimaryInverse
    );
}

function executeSwap(SwapRequest memory _swapRequest)
    external
    payable
    onlyEligibleUser
    onlyExistingRoute(_swapRequest.routeId)
    nonReentrant
    returns (uint256 _amountOut)
{
    if (_swapRequest.amount == 0) revert InvalidAmount();
    RouteData memory swapImplInfo = routes[_swapRequest.routeId];
    if (swapImplInfo.isBridge) revert RouteNotAllowedForThisAction();

    if (_swapRequest.checkForSlippage && _swapRequest.minAmount == 0) {
        // set minAmount so that slippage can be checked
        uint256 _slippageTolerance = slippageTolerance[_swapRequest.inputToken][_swapRequest.outputToken];
        if (_slippageTolerance == 0) {
            _slippageTolerance = genericSlippageTolerance;
        }
        INoyaValueOracle _priceOracle = INoyaValueOracle(valueOracle);
        uint256 _outputTokenValue =
            _priceOracle.getValue(_swapRequest.inputToken, _swapRequest.outputToken, _swapRequest.amount);

        _swapRequest.minAmount = (((1e6 - _slippageTolerance) * _outputTokenValue) / 1e6);
    }

    _amountOut = ISwapAndBridgeImplementation(swapImplInfo.route).performSwapAction(msg.sender, _swapRequest);

    emit ExecutionCompleted(
        _swapRequest.routeId, _swapRequest.amount, _amountOut, _swapRequest.inputToken, _swapRequest.outputToken
    );
}

function getValueFromChainlinkFeed(
    AggregatorV3Interface source,
    uint256 amountIn,
    uint256 sourceTokenUnit,
    bool isInverse
) public view returns (uint256) {
    int256 price;
    uint256 updatedAt;
    (, price,, updatedAt,) = source.latestRoundData();
    uint256 uintprice = uint256(price);
    if (block.timestamp - updatedAt > chainlinkPriceAgeThreshold) {
        revert NoyaChainlinkOracle_DATA_OUT_OF_DATE();
    }
    if (price <= 0) {
        revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(address(source), address(0), address(0));
    }
    if (isInverse) {
        return (amountIn * sourceTokenUnit) / uintprice;
    }
    return (amountIn * uintprice) / (sourceTokenUnit);
}

