function exchangeOldForCanonical(address bridgeTokenAddress, uint256 tokenAmount) external nonReentrant validBridgeToken(bridgeTokenAddress) returns (uint256 canonicalTokensOut) {
    if (exchangesPaused) {
        revert IllegalState();
    }

    if (!bridgeTokenEnabled[bridgeTokenAddress]) {
        revert IllegalState();
    }

    // Pull in the old tokens
    TokenUtils.safeTransferFrom(bridgeTokenAddress, msg.sender, address(this), tokenAmount);

    // Handle the fee, if applicable
    canonicalTokensOut = tokenAmount;
    if (!_isFeeExempt(msg.sender)) {
        canonicalTokensOut -= ((canonicalTokensOut * swapFees[bridgeTokenAddress][0]) / FEE_PRECISION);
    }

    // Mint canonical tokens and give it to the sender
    super._mint(msg.sender, canonicalTokensOut);
}

function exchangeCanonicalForOld(address bridgeTokenAddress, uint256 tokenAmount) external nonReentrant validBridgeToken(bridgeTokenAddress) returns (uint256 bridgeTokensOut) {
    if (exchangesPaused) {
        revert IllegalState();
    }

    if (!bridgeTokenEnabled[bridgeTokenAddress]) {
        revert IllegalState();
    }

    // Burn the canonical tokens
    super._burn(msg.sender, tokenAmount);

    // Handle the fee, if applicable
    bridgeTokensOut = tokenAmount;
    if (!_isFeeExempt(msg.sender)) {
        bridgeTokensOut -= ((bridgeTokensOut * swapFees[bridgeTokenAddress][1]) / FEE_PRECISION);
    }

    // Give old tokens to the sender
    TokenUtils.safeTransfer(bridgeTokenAddress, msg.sender, bridgeTokensOut);
}

function execute(
    address destination,
    bytes calldata data,
    uint256 gasLimit,
    address executor,
    bytes32[] memory sigR,
    bytes32[] memory sigS,
    uint8[] memory sigV,
    uint256 deadline
) public {
    require(isOwner[msg.sender], "Not an owner");
    require(sigR.length == threshold, "Not enough signatures");
    require(sigR.length == sigS.length && sigR.length == sigV.length, "Lengths do not match");
    require(executor == msg.sender, "Invalid executor");
    require(block.timestamp <= deadline, "Transaction expired");
    {
        bytes32 txInputHash =
            keccak256(abi.encode(TXTYPE_HASH, nonce, destination, data, gasLimit, executor, deadline));
        bytes32 totalHash = keccak256(abi.encodePacked("\x19\x01", _domainSeparatorV4(), txInputHash));
        address lastAdd = address(0);
        for (uint256 i = 0; i < threshold;) {
            address recovered = ECDSA.recover(totalHash, sigV[i], sigR[i], sigS[i]);
            require(recovered > lastAdd && isOwner[recovered]);
            lastAdd = recovered;
            unchecked {
                ++i;
            }
        }

        nonce++;
    }
    emit Execute(destination, data, gasLimit, executor, deadline);
    (bool success,) = destination.call{ gas: gasLimit }(data);
    require(success, "Transaction execution reverted.");
}

function getValue(address asset, address baseToken, uint256 amount) public view returns (uint256) {
    if (asset == baseToken) {
        return amount;
    }

    (address primarySource, bool isPrimaryInverse) = getSourceOfAsset(asset, baseToken);
    if (primarySource == address(0)) {
        revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(asset, baseToken, primarySource);
    }
    address decimalsSource = isPrimaryInverse ? baseToken : asset;
    decimalsSource = decimalsSource == ETH || decimalsSource == USD ? primarySource : decimalsSource;
    return getValueFromChainlinkFeed(
        AggregatorV3Interface(primarySource), amount, getTokenDecimals(decimalsSource), isPrimaryInverse
    );
}

