    address[] memory tokensIn,
    address[] memory tokensOut,
    uint256[] memory amountsIn,
    bytes[] memory swapData,
    uint256[] memory routeIds
) external onlyManager nonReentrant {
    for (uint256 i = 0; i < tokensIn.length; i++) {
        _executeSwap(
            SwapRequest(address(this), routeIds[i], amountsIn[i], tokensIn[i], tokensOut[i], swapData[i], true, 0)
        );
        _updateTokenInRegistry(tokensIn[i]);
        _updateTokenInRegistry(tokensOut[i]);
        emit SwapHoldings(tokensIn[i], tokensOut[i], amountsIn[i], swapData[i]);
    }
}

function performSwapAction(address caller, SwapRequest calldata _request)
    external
    payable
    override
    onlyHandler
    returns (uint256)
{
    require(verifySwapData(_request), "LifiImplementation: INVALID_SWAP_DATA");
    uint256 balanceOut0 = 0;
    if (_request.outputToken == address(0)) {
        balanceOut0 = address(_request.from).balance;
    } else {
        balanceOut0 = IERC20(_request.outputToken).balanceOf(_request.from);
    }
    _forward(IERC20(_request.inputToken), _request.from, _request.amount, caller, _request.data, _request.routeId);
    uint256 balanceOut1 = 0;
    if (_request.outputToken == address(0)) {
        balanceOut1 = address(_request.from).balance;
    } else {
        balanceOut1 = IERC20(_request.outputToken).balanceOf(_request.from);
    }

    emit Swapped(balanceOut0, balanceOut1, _request.outputToken);

    return balanceOut1 - balanceOut0;
}

function executeSwap(SwapRequest memory _swapRequest)
    external
    payable
    onlyEligibleUser
    onlyExistingRoute(_swapRequest.routeId)
    nonReentrant
    returns (uint256 _amountOut)
{
    if (_swapRequest.amount == 0) revert InvalidAmount();
    RouteData memory swapImplInfo = routes[_swapRequest.routeId];
    if (swapImplInfo.isBridge) revert RouteNotAllowedForThisAction();

    if (_swapRequest.checkForSlippage && _swapRequest.minAmount == 0) {
        // set minAmount so that slippage can be checked
        uint256 _slippageTolerance = slippageTolerance[_swapRequest.inputToken][_swapRequest.outputToken];
        if (_slippageTolerance == 0) {
            _slippageTolerance = genericSlippageTolerance;
        }
        INoyaValueOracle _priceOracle = INoyaValueOracle(valueOracle);
        uint256 _outputTokenValue =
            _priceOracle.getValue(_swapRequest.inputToken, _swapRequest.outputToken, _swapRequest.amount);

        _swapRequest.minAmount = (((1e6 - _slippageTolerance) * _outputTokenValue) / 1e6);
    }

    _amountOut = ISwapAndBridgeImplementation(swapImplInfo.route).performSwapAction(msg.sender, _swapRequest);

    emit ExecutionCompleted(
        _swapRequest.routeId, _swapRequest.amount, _amountOut, _swapRequest.inputToken, _swapRequest.outputToken
    );
}

function verifySwapData(SwapRequest calldata _request) public view override returns (bool) {
    bytes4 selector = bytes4(_request.data[:4]);
    if (selector != LI_FI_GENERIC_SWAP_SELECTOR) {
        revert InvalidSelector();
    }
    (address sendingAssetId, uint256 amount, address from, address receivingAssetId, uint256 receivingAmount) =
        ILiFi(lifi).extractGenericSwapParameters(_request.data);

    if (from != _request.from) revert InvalidReceiver(from, _request.from);
    if (receivingAmount < _request.minAmount) revert InvalidMinAmount();
    if (sendingAssetId != _request.inputToken) revert InvalidInputToken();
    if (receivingAssetId != _request.outputToken) revert InvalidOutputToken();
    if (amount != _request.amount) revert InvalidAmount();

    return true;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 startingBalance = IERC20(underlyingToken).balanceOf(address(this));

    uint256 error;
    if ((error = ICERC20(token).redeem(amount)) != NO_ERROR) {
        revert FuseError(error);
    }

    uint256 endingBalance = IERC20(underlyingToken).balanceOf(address(this));
    uint256 redeemedAmount = endingBalance - startingBalance;

    SafeERC20.safeTransfer(underlyingToken, recipient, redeemedAmount);

    return redeemedAmount;
}

