        IERC20(bridgeToken).approve(address(router), amt2Bridge);
    }

    router.bridgeWithPayload{value: msg.value}(
        lzIdLookup[dstChainId],
        destinationBridgeAdapter[dstChainId],
        swapParams.amountIn,
        false,
        dstGas,
        bridgePayload
    );
}

